32	BaseScreen* USBTransferScreen::handle_input(Controller& controller, const worker_map_t& workers) {
33	  auto button1 = workers.worker<ZenButton>(k_worker_button_1);
34	  auto button2 = workers.worker<ZenButton>(k_worker_button_2);
35	  auto button3 = workers.worker<ZenButton>(k_worker_button_3);
36	
37	  // Handle button inputs
38	  if (button1->is_fresh() && button1->get_data().shortPress) {
39	    _button1_pressed = true;
40	    M5_LOGD("Button 1 pressed in USB Transfer screen");
41	    
42	    if (_transfer_state == e_usb_active) {
43	      // If USB is active, disable it
44	      disableUSBStorage();
45	    } else if (_transfer_state == e_idle) {
46	      // If idle, try to enable USB storage
47	      enableUSBStorage();
48	    }
49	    force_next_render();
50	    return nullptr;
51	  }
52	  
53	  if (button2->is_fresh() && button2->get_data().shortPress) {
54	    _button2_pressed = true;
55	    M5_LOGD("Button 2 pressed in USB Transfer screen");
56	    
57	    // Refresh SD card info and USB state
58	    updateSDCardInfo();
59	    force_next_render();
60	    return nullptr;
61	  }
62	  
63	  if (button3->is_fresh() && button3->get_data().shortPress) {
64	    _button3_pressed = true;
65	    M5_LOGD("Button 3 pressed in USB Transfer screen");
66	    
67	    // Return to main menu
68	    return &MenuWindow_i;
69	  }
70	  
71	  return nullptr;
72	}
