74	void USBTransferScreen::render(const worker_map_t& workers, const handler_map_t& handlers, bool force) {
75	  if (!force) {
76	    return;
77	  }
78	
79	  clear_screen_content();
80	  
81	  // Update USB state more frequently during transitions
82	  uint32_t current_time = millis();
83	  uint32_t update_interval = USB_STATE_CHECK_INTERVAL;
84	  
85	  // During USB operations, update more frequently for smooth progress
86	  if (_transfer_state == e_enabling_usb || _transfer_state == e_disabling_usb) {
87	    update_interval = 100; // Update every 100ms during USB operations
88	  }
89	  
90	  if (current_time - _last_progress_update >= update_interval) {
91	    updateUSBState();
92	    _last_progress_update = current_time;
93	  }
94	  
95	  // Draw different UI based on current state
96	  drawStatusInfo();
97	  drawUSBStatus();
98	  drawTransferProgress();
99	  drawButtonLabels();
100	}
101	
102	void USBTransferScreen::enter_screen(Controller& controller) {
103	  M5_LOGD("Entering USB Transfer screen");
104	  
105	  // Initialize state
106	  _transfer_state = e_idle;
107	  _last_state_change = millis();
108	  _last_progress_update = millis();
109	  _transfer_progress = 0;
110	  _usb_connected = false;
111	  _usb_available = false;
112	  
113	  // Check SD card status
114	  if (!SDInterface::i().ready()) {
115	    _transfer_state = e_error;
116	    strncpy(_status_message, "NO SD CARD INSERTED", sizeof(_status_message));
117	    M5_LOGD("SD card not available on enter_screen");
118	  } else {
119	    // Get SD card information
120	    updateSDCardInfo();
121	    strncpy(_status_message, "Ready to enable USB storage", sizeof(_status_message));
122	  }
123	  
124	  force_next_render();
125	}
126	
127	void USBTransferScreen::leave_screen(Controller& controller) {
128	  M5_LOGD("Leaving USB Transfer screen");
129	  
130	  // If USB storage was enabled, disable it for safety
131	  if (_transfer_state == e_usb_active) {
132	    disableUSBStorage();
133	  }
134	}
