171	    case e_idle:
172	      M5.Lcd.setTextColor(LCD_COLOR_DEFAULT, LCD_COLOR_BACKGROUND);
173	      M5.Lcd.printf("  Ready to enable USB storage\n");
174	      M5.Lcd.printf("  Device: %s\n", _usb_device_name);
