176	      
177	    case e_enabling_usb:
178	      M5.Lcd.setTextColor(LCD_COLOR_ACTIVITY, LCD_COLOR_BACKGROUND);
179	      M5.Lcd.printf("  Enabling USB storage...\n");
180	      break;
181	      
182	    case e_usb_active:
183	      M5.Lcd.setTextColor(LCD_COLOR_ACTIVITY, LCD_COLOR_BACKGROUND);
184	      M5.Lcd.printf("  USB storage ACTIVE\n");
185	      M5.Lcd.printf("  Connect USB-C cable to computer\n");
186	      M5.Lcd.printf("  Files accessible via file browser\n");
187	      break;
188	      
189	    case e_disabling_usb:
190	      M5.Lcd.setTextColor(LCD_COLOR_STALE_INCOMPLETE, LCD_COLOR_BACKGROUND);
191	      M5.Lcd.printf("  Disabling USB storage...\n");
