201	void USBTransferScreen::drawTransferProgress() {
202	  if (_transfer_state == e_enabling_usb || _transfer_state == e_disabling_usb) {
203	    M5.Lcd.setTextColor(LCD_COLOR_DEFAULT, LCD_COLOR_BACKGROUND);
204	    M5.Lcd.setCursor(0, 160);
205	    M5.Lcd.setTextFont(2);
206	    
207	    M5.Lcd.printf("Progress: %lu%%\n", _transfer_progress);
208	    
209	    // Draw progress bar
210	    int bar_width = 280;
211	    int bar_height = 10;
212	    int bar_x = 20;
213	    int bar_y = 180;
214	    
215	    // Draw background
216	    M5.Lcd.drawRect(bar_x, bar_y, bar_width, bar_height, LCD_COLOR_DEFAULT);
217	    
218	    // Draw progress
219	    int progress_width = (bar_width - 2) * _transfer_progress / 100;
220	    M5.Lcd.fillRect(bar_x + 1, bar_y + 1, progress_width, bar_height - 2, LCD_COLOR_ACTIVITY);
221	  }
222	}
