224	void USBTransferScreen::drawButtonLabels() {
225	  switch (_transfer_state) {
226	    case e_idle:
227	    case e_error:
228	      drawButton1("Enable USB");
229	      break;
230	    case e_usb_active:
231	      drawButton1("Disable USB");
232	      break;
233	    case e_enabling_usb:
234	    case e_disabling_usb:
235	      drawButton1("Please Wait", BaseScreen::e_button_disabled);
236	      break;
237	  }
238	  
239	  drawButton2("Refresh");
240	  drawButton3("Menu");
241	}
