109	/**
110	 * We note that for the ESP32, the SD library is robust to multiple call to the begin() function
111	 * @return true if ready
112	 */
113	bool SDInterface::begin() {
114	  static bool _first_try = true;
115	  if (!ready() && (_first_try || (millis() - _last_try > 5000))) {
116	    _first_try = false;
117	    _last_try = millis();
118	    if (SD.begin(SD_CS_PIN)) {
119	      bool zen_test = SD.exists(TEST_FILENAME);
120	      if (!zen_test) {
121	        auto new_file = SD.open(TEST_FILENAME, FILE_WRITE);
122	        if (new_file) {
123	          new_file.close();
124	        }
125	      }
126	      _status = SD.exists(TEST_FILENAME) ? e_sd_config_status_config_no_content : e_sd_config_status_not_ready;
127	    }
128	  }
129	  return ready();
130	}
