151	bool SDInterface::log_println(const char* log_name, const char* data) {
152	  if (!ready()) {
153	    return false;
154	  }
155	  if (!SD.exists(log_name)) {
156	    // Attempt to auto-create the missing file and its parent directory
157	    String path = String(log_name);
158	    int last_slash = path.lastIndexOf('/');
159	    if (last_slash > 0) {
160	      String dir = path.substring(0, last_slash);
161	      if (!SD.exists(dir.c_str())) {
162	        M5_LOGD("Creating directory '%s' for missing log file", dir.c_str());
163	        SD.mkdir(dir.c_str());
164	      }
165	    }
166	
167	    // Create the file
168	    File create_file = SD.open(log_name, FILE_WRITE);
169	    if (!create_file) {
170	      end();
171	      M5_LOGD("Unable to create log file \"%s\".", log_name);
172	      return false;
173	    }
174	    create_file.close();
175	
176	    // If still doesn't exist, give up
177	    if (!SD.exists(log_name)) {
178	      M5_LOGD("Unable to log to non-existent file \"%s\" after creation attempt.", log_name);
179	      return false;
180	    }
181	  }
182	  // open the setup file in append mode to add lines
183	  auto log_file = SD.open(log_name, FILE_APPEND);
184	  if (!log_file) {
185	    end();
186	    M5_LOGD("Unable to open log file \"%s\".", log_name);
187	    return false;
188	  }
189	
190	  log_file.println(data);
191	
192	//  M5_LOGD("Logged '%s' to '%s'.", data, log_name);
193	
194	  log_file.close();
195	  _last_write = millis();
196	  return true;
197	}
