199	SDInterface::SdStatus SDInterface::has_safezen_content(uint16_t device_id) {
200	  if (!ready()) {
201	    _status = e_sd_config_status_not_ready;
202	    return _status;
203	  }
204	
205	  if (!SD.exists(SETUP_FILENAME)) {
206	    return _status = e_sd_config_status_no_config_file;
207	  }
208	
209	  // open the setup file
210	  auto setup_file = SD.open(SETUP_FILENAME, FILE_READ);
211	  _last_read = millis();
212	
213	  if (!setup_file) {
214	    return _status = e_sd_config_status_config_no_content;
215	  }
216	
217	  _device_id = 0;
218	
219	  while (setup_file.available()) {
220	    String line = setup_file.readStringUntil('\n');
221	    if (line.startsWith(SD_CONFIG_FIELD_DEVICE_ID)) {
222	      sscanf(line.c_str(), sd_config_device_id_f, &_device_id);
223	      break;
224	    }
225	  }
226	
227	  // close the setup file
228	  setup_file.close();
229	
230	  if (_device_id == 0) {
231	    _status = e_sd_config_status_config_no_content;
232	  } else if (device_id && _device_id != device_id) {
233	    _status = e_sd_config_status_config_different_id;
234	  } else {
235	    _status = e_sd_config_status_ok;
236	  }
237	  return _status;
238	}
