240	bool SDInterface::read_safezen_file_to_settings(LocalStorage& settings) {
241	  M5_LOGD("read_safezen_file_to_settings");
242	  if (!ready()) {
243	    return false;
244	  }
245	
246	  File safecast_txt = SD.open(SETUP_FILENAME, FILE_READ);
247	  if (!safecast_txt) {
248	    return false;
249	  }
250	  _last_read = millis();
251	
252	  char version[CONFIG_VAL_MAX] = "";
253	
254	  String first_line = safecast_txt.readStringUntil('\n');
255	  if (first_line.startsWith(SD_CONFIG_FIELD_VERSION)) {
256	    sscanf(first_line.c_str(), sd_config_version_f, version);
257	  } else {
258	    // No version line read, expect latest version
259	    strcpy(version, VERSION_NUMBER);
260	    // Reopen settings, because first line was (probably) some configuration
261	    safecast_txt.close();
262	    safecast_txt = SD.open(SETUP_FILENAME, FILE_READ);
263	    if (!safecast_txt) {
264	      return false;
265	    }
266	  }
267	
268	  // Add earlier / non-compatible versions here too
269	  if (strcmp(version, VERSION_NUMBER) == 0) {
270	    return read_safezen_file_latest(settings, safecast_txt);
271	  }
272	
273	  // try with latest, at this point it should at least get the id
274	  return read_safezen_file_latest(settings, safecast_txt);
275	}
