277	bool SDInterface::read_safezen_file_latest(LocalStorage& settings, File& file) {
278	  // Device settings
279	  char access_point_password[CONFIG_VAL_MAX] = "";
280	  uint32_t alert_threshold = 0;
281	  uint8_t cpm_usvh = false;
282	  uint8_t manual_logging = false;
283	  uint8_t enable_journal = true;
284	  uint8_t log_void = true;  // Always set to true to include invalid lines
285	  uint32_t screen_dim_timeout = 0;
286	  uint32_t screen_off_timeout = 0;
287	  uint8_t animated_screensaver = true;
288	  uint8_t error_alert_sound = true;
289	  uint8_t dim_brightness = D_DIM_BRIGHTNESS;
290	  uint8_t audio_volume = D_AUDIO_VOLUME;
291	  uint8_t sound_enabled = 1;
292	
293	  // Connection settings
294	  char wifi_ssid[CONFIG_VAL_MAX] = "";
295	  char wifi_password[CONFIG_VAL_MAX] = "";
296	  char wifi_ssid2[CONFIG_VAL_MAX] = "";
297	  char wifi_password2[CONFIG_LONG_VAL_MAX] = "";
298	  uint8_t wifi_profile_active = 1;
299	  char api_key[CONFIG_VAL_MAX] = "";
300	  char user_name[CONFIG_VAL_MAX] = "";
301	
302	  // Location settings
303	  double fixed_latitude = 0;
304	  double fixed_longitude = 0;
305	  float fixed_range = 0;
306	  uint16_t max_dop = 0;
307	
308	  while (file.available()) {
309	    String line = file.readStringUntil('\n');
310	    if (line.length() == 0) {
311	      continue;
312	    }
313	    else if (line.startsWith(SD_CONFIG_FIELD_DEVICE_ID)) {
314	      if (sscanf(line.c_str(), sd_config_device_id_f, &_device_id)) {
315	        settings.set_device_id(_device_id, true);
316	        M5_LOGD("Loaded from SD: device_id=%d", _device_id);
317	      }
318	    }
319	    else if (line.startsWith(SD_CONFIG_FIELD_USER_NAME)) {
320	      if (sscanf(line.c_str(), sd_config_user_name_f, user_name)) {
321	        settings.set_user_name(user_name, true);
322	        M5_LOGD("Loaded from SD: user_name=%d", user_name);
323	      }
324	      else {
325	        M5_LOGD("Unable to load user_name");
326	      }
327	    }
328	    else if (line.startsWith(SD_CONFIG_FIELD_API_KEY)) {
329	      if (_device_id && line.length() - strlen(SD_CONFIG_FIELD_API_KEY) < CONFIG_VAL_MAX && sscanf(line.c_str(), sd_config_api_key_f, api_key)) {
330	        settings.set_api_key(api_key, true);
331	        M5_LOGD("Loaded from SD: api_key=%s", api_key);
332	      } else {
333	        M5_LOGD("Unable to load api_key");
334	      }
335	    }
336	    else if (line.startsWith(SD_CONFIG_FIELD_ACCESS_POINT_PASSWORD)) {
337	      if (_device_id && line.length() - strlen(SD_CONFIG_FIELD_ACCESS_POINT_PASSWORD) < CONFIG_VAL_MAX && sscanf(line.c_str(), sd_config_access_point_password_f, access_point_password)) {
338	        settings.set_ap_password(access_point_password, true);
339	        M5_LOGD("Loaded from SD: access_point_password=%s", access_point_password);
340	      } else {
341	        M5_LOGD("Unable to load access_point_password");
342	      }
343	    }
344	    // Check wifi_ssid2 and wifi_password2 BEFORE wifi_ssid and wifi_password
345	    // because "wifi_ssid2" starts with "wifi_ssid" and would match incorrectly
346	    else if (line.startsWith(SD_CONFIG_FIELD_WIFI_SSID2)) {
347	      if (_device_id && line.length() - strlen(SD_CONFIG_FIELD_WIFI_SSID2) < CONFIG_VAL_MAX && sscanf(line.c_str(), sd_config_wifi_ssid2_f, wifi_ssid2)) {
348	        settings.set_wifi_ssid2(wifi_ssid2, true);
349	        M5_LOGD("Loaded from SD: wifi_ssid2=%s", wifi_ssid2);
350	      } else {
351	        M5_LOGD("Unable to load wifi_ssid2");
352	      }
353	    }
354	    else if (line.startsWith(SD_CONFIG_FIELD_WIFI_PASSWORD2)) {
355	      if (_device_id && line.length() - strlen(SD_CONFIG_FIELD_WIFI_PASSWORD2) < CONFIG_LONG_VAL_MAX && sscanf(line.c_str(), sd_config_wifi_password2_f, wifi_password2)) {
356	        settings.set_wifi_password2(wifi_password2, true);
357	        M5_LOGD("Loaded from SD: wifi_password2=%s", wifi_password2);
358	      } else {
359	        M5_LOGD("Unable to load wifi_password2");
360	      }
361	    }
362	    else if (line.startsWith(SD_CONFIG_FIELD_WIFI_SSID)) {
363	      if (_device_id && line.length() - strlen(SD_CONFIG_FIELD_WIFI_SSID) < CONFIG_VAL_MAX && sscanf(line.c_str(), sd_config_wifi_ssid_f, wifi_ssid)) {
364	        settings.set_wifi_ssid(wifi_ssid, true);
365	        M5_LOGD("Loaded from SD: wifi_ssid=%s", wifi_ssid);
366	      } else {
367	        M5_LOGD("Unable to load wifi_ssid");
368	      }
369	    }
370	    else if (line.startsWith(SD_CONFIG_FIELD_WIFI_PASSWORD)) {
371	      if (_device_id && line.length() - strlen(SD_CONFIG_FIELD_WIFI_PASSWORD) < CONFIG_VAL_MAX && sscanf(line.c_str(), sd_config_wifi_password_f, wifi_password)) {
372	        settings.set_wifi_password(wifi_password, true);
373	        M5_LOGD("Loaded from SD: wifi_password=%s", wifi_password);
374	      } else {
375	        M5_LOGD("Unable to load wifi_password");
376	      }
377	    }
378	    else if (line.startsWith(SD_CONFIG_FIELD_WIFI_PROFILE)) {
379	      if (_device_id && sscanf(line.c_str(), sd_config_wifi_profile_f, &wifi_profile_active)) {
380	        settings.set_wifi_profile_active(wifi_profile_active, true);
381	        M5_LOGD("Loaded from SD: wifi_profile_active=%u", wifi_profile_active);
382	      } else {
383	        M5_LOGD("Unable to load wifi_profile");
384	      }
385	    }
386	    else if (line.startsWith(SD_CONFIG_FIELD_ALARM_THRESHOLD)) {
387	      if (_device_id && sscanf(line.c_str(), sd_config_alert_threshold_f, &alert_threshold)) {
388	        settings.set_alert_threshold(alert_threshold, true);
389	        M5_LOGD("Loaded from SD: alert_threshold=%d", alert_threshold);
