397	    }
398	    else if (line.startsWith(SD_CONFIG_FIELD_MANUAL_LOGGING)) {
399	      if (_device_id && sscanf(line.c_str(), sd_config_manual_logging_f, &manual_logging)) {
400	        settings.set_manual_logging(!!manual_logging, true);
