403	    }
404	    else if (line.startsWith(SD_CONFIG_FIELD_ENABLE_JOURNAL)) {
405	      if (_device_id && sscanf(line.c_str(), sd_config_enable_journal_f, &enable_journal)) {
406	        settings.set_enable_journal(!!enable_journal, true);
407	        M5_LOGD("Loaded from SD: enable_journal=%d", !!enable_journal);
408	      }
409	    }
410	    else if (line.startsWith(SD_CONFIG_FIELD_LOG_VOID)) {
411	      if (_device_id && sscanf(line.c_str(), sd_config_log_void_f, &log_void)) {
412	        settings.set_log_void(!!log_void, true);
