630	bool SDInterface::rename_log(const char* old_log_name, const char* new_log_name) {
631	  if (!ready()) {
632	    M5_LOGE("Cannot rename: SD card not ready");
633	    return false;
634	  }
635	
636	  if (!SD.exists(old_log_name)) {
637	    M5_LOGE("Cannot rename: source file '%s' does not exist", old_log_name);
638	    return false;
639	  }
640	  
641	  // Check if target already exists. If so, assume rename was successful already.
642	  if (SD.exists(new_log_name)) {
643	    M5_LOGW("Target file '%s' already exists, assuming rename is complete.", new_log_name);
644	    // If the original file still exists, something is wrong. Let's remove it.
645	    if(SD.exists(old_log_name)) {
646	        SD.remove(old_log_name);
647	    }
648	    return true;
649	  }
650	  
651	  // Extract directory from new_log_name and ensure it exists
652	  String new_path = String(new_log_name);
653	  int last_slash = new_path.lastIndexOf('/');
654	  if (last_slash > 0) {
655	    String dir = new_path.substring(0, last_slash);
656	    if (!SD.exists(dir.c_str())) {
657	      M5_LOGD("Creating directory '%s' for rename", dir.c_str());
658	      if (!SD.mkdir(dir.c_str())) {
659	        M5_LOGE("Failed to create directory '%s'", dir.c_str());
660	        return false;
661	      }
662	    }
663	  }
664	  
665	  bool success = SD.rename(old_log_name, new_log_name);
666	  
667	  // Verify the renamed file exists
668	  if (success && !SD.exists(new_log_name)) {
669	    M5_LOGE("Rename reported success but file '%s' does not exist", new_log_name);
670	    success = false;
671	  }
672	  
673	  if (success) {
674	    M5_LOGD("Successfully renamed '%s' to '%s'", old_log_name, new_log_name);
675	  } else {
676	    M5_LOGE("Failed to rename '%s' to '%s'", old_log_name, new_log_name);
677	  }
678	
679	  return success;
