690	void SDInterface::delete_directory(const char* dirPath) {
691	  File dir = SD.open(dirPath);
692	  if (!dir) {
693	    M5_LOGD("Directory does not exist or could not be opened.");
694	    return;
695	  }
696	
697	  if (!dir.isDirectory()) {
698	    M5_LOGD("The specified path is not a directory.");
699	    dir.close();
700	    return;
701	  }
702	
703	  // Iterate through all files in the directory
704	  while (true) {
705	    File entry = dir.openNextFile();
706	    if (!entry) {
707	      // No more files in the directory
708	      break;
709	    }
710	
711	    // Construct the full path
712	    String fullPath = String(dirPath) + "/" + entry.name();
713	
714	    if (entry.isDirectory()) {
715	      // Recursively delete subdirectories
716	      M5_LOGD("Recursively deleting directory: %s", fullPath.c_str());
717	      delete_directory(fullPath.c_str());
718	
719	      // Attempt to remove the directory itself after its contents are deleted
720	      if (!SD.rmdir(fullPath.c_str())) {
721	        M5_LOGD("Failed to remove directory: %s", fullPath.c_str());
722	      } else {
723	        M5_LOGD("Successfully removed directory: %s", fullPath.c_str());
724	      }
725	    } else {
726	      // Try to delete the file
727	      if (!SD.remove(fullPath.c_str())) {
728	        M5_LOGD("Failed to delete file: %s", fullPath.c_str());
729	      } else {
730	        M5_LOGD("Successfully deleted file: %s", fullPath.c_str());
731	      }
732	    }
733	    entry.close();
734	  }
735	
736	  dir.close();
737	
738	  // Finally, remove the empty directory itself
739	  if (SD.rmdir(dirPath)) {
740	    M5_LOGD("Directory deleted successfully: %s", dirPath);
741	  } else {
742	    M5_LOGD("Failed to delete the directory: %s", dirPath);
743	  }
