#ifndef USER_CONFIG_H_
#define USER_CONFIG_H_

#include <M5Unified.hpp>

/** System config **/
#define STR(x) TOSTRING(x)
#define TOSTRING(x) #x

/*** VERSION ***/
// Version defined in platformio.ini in [env] build flags
#define VERSION_NUMBER STR(MAJOR_VERSION) "." STR(MINOR_VERSION) "." STR(PATCH_VERSION)
#define VERSION_STRING "bGeigieZen " VERSION_NUMBER
#define VERSION_SIMPLE_STRING "" VERSION_NUMBER

/*** USER ***/
// User name for screens
#define USER_NAME STR(config.user_name)
#define USER_STRING "USER " USER_NAME

/** DEVICE ID ****/
#define DEVICE_NAME STR(config.device_id)
#define DEVICE_STRING "DEVICE " DEVICE_NAME

/*** COPYRIGHT ***/
// Copyright year for screens
#define COPYRIGHT_YEAR 2026
#define COPYRIGHT_YEAR_STRING STR(COPYRIGHT_YEAR)

/***************/

/*** CONFIG ***/
// - geiger counter
constexpr uint8_t GEIGER_AVERAGING_N_BINS = 60;  // 60 x 1 s == 1 min moving average
constexpr uint8_t GEIGER_AVERAGING_PERIOD_S = 1;  // 1 s
