// Other
constexpr char SCREENSAVER_TEXT[] = VERSION_STRING;
// constexpr char SCREENSAVER_TEXT[] = USER_STRING "/n" DEVICE_STRING;



/**************/


/** Hardware pins settings **/
// TODO

