20	extern "C" uint16_t tusb_msc_load_descriptor(uint8_t * dst, uint8_t * itf)
21	{
22	    uint8_t str_index = tinyusb_add_string_descriptor("TinyUSB MSC");
23	    uint8_t ep_num = tinyusb_get_free_duplex_endpoint();
24	    TU_VERIFY (ep_num != 0);
25	    uint8_t descriptor[TUD_MSC_DESC_LEN] = {
26	        // Interface number, string index, EP Out & EP In address, EP size
27	        TUD_MSC_DESCRIPTOR(*itf, str_index, ep_num, (uint8_t)(0x80 | ep_num), 64)
28	    };
29	    *itf+=1;
30	    memcpy(dst, descriptor, TUD_MSC_DESC_LEN);
31	    return TUD_MSC_DESC_LEN;
32	}
