34	typedef struct {
35	    bool media_present;
36	    uint8_t vendor_id[8];
37	    uint8_t product_id[16];
38	    uint8_t product_rev[4];
39	    uint16_t block_size;
40	    uint32_t block_count;
41	    bool (*start_stop)(uint8_t power_condition, bool start, bool load_eject);
42	    int32_t (*read)(uint32_t lba, uint32_t offset, void* buffer, uint32_t bufsize);
43	    int32_t (*write)(uint32_t lba, uint32_t offset, uint8_t* buffer, uint32_t bufsize);
44	} msc_lun_t;
45	
46	static const uint8_t MSC_MAX_LUN = 3;
47	static uint8_t MSC_ACTIVE_LUN = 0;
48	static msc_lun_t msc_luns[MSC_MAX_LUN];
49	
50	static void cplstr(void *dst, const void * src, size_t max_len){
51	    if(!src || !dst || !max_len){
52	        return;
53	    }
54	    size_t l = strlen((const char *)src);
55	    if(l > max_len){
56	        l = max_len;
57	    }
58	    memcpy(dst, src, l);
59	}
