61	// Invoked when received GET_MAX_LUN request, required for multiple LUNs implementation
62	uint8_t tud_msc_get_maxlun_cb(void)
63	{
64	    log_v("%u", MSC_ACTIVE_LUN);
65	    return MSC_ACTIVE_LUN;
66	}
67	
68	// Invoked when received SCSI_CMD_INQUIRY
69	// Application fill vendor id, product id and revision with string up to 8, 16, 4 characters respectively
70	void tud_msc_inquiry_cb(uint8_t lun, uint8_t vendor_id[8], uint8_t product_id[16], uint8_t product_rev[4])
71	{
72	    log_v("[%u]", lun);
73	    cplstr(vendor_id  , msc_luns[lun].vendor_id, 8);
74	    cplstr(product_id , msc_luns[lun].product_id, 16);
75	    cplstr(product_rev, msc_luns[lun].product_rev, 4);
76	}
77	
78	// Invoked when received Test Unit Ready command.
79	// return true allowing host to read/write this LUN e.g SD card inserted
80	bool tud_msc_test_unit_ready_cb(uint8_t lun)
81	{
82	    log_v("[%u]: %u", lun, msc_luns[lun].media_present);
83	    return msc_luns[lun].media_present; // RAM disk is always ready
84	}
85	
86	// Invoked when received SCSI_CMD_READ_CAPACITY_10 and SCSI_CMD_READ_FORMAT_CAPACITY to determine the disk size
87	// Application update block count and block size
88	void tud_msc_capacity_cb(uint8_t lun, uint32_t* block_count, uint16_t* block_size)
89	{
90	    log_v("[%u]", lun);
91	    if(!msc_luns[lun].media_present){
92	        *block_count = 0;
93	        *block_size  = 0;
94	        return;
95	    }
96	
97	    *block_count = msc_luns[lun].block_count;
98	    *block_size  = msc_luns[lun].block_size;
99	}
100	
101	// Invoked when received Start Stop Unit command
102	// - Start = 0 : stopped power mode, if load_eject = 1 : unload disk storage
103	// - Start = 1 : active mode, if load_eject = 1 : load disk storage
104	bool tud_msc_start_stop_cb(uint8_t lun, uint8_t power_condition, bool start, bool load_eject)
105	{
106	    log_v("[%u] power: %u, start: %u, eject: %u", lun, power_condition, start, load_eject);
107	    if(msc_luns[lun].start_stop){
108	        return msc_luns[lun].start_stop(power_condition, start, load_eject);
109	    }
110	    return true;
111	}
112	
113	// Callback invoked when received READ10 command.
114	// Copy disk's data to buffer (up to bufsize) and return number of copied bytes.
115	int32_t tud_msc_read10_cb(uint8_t lun, uint32_t lba, uint32_t offset, void* buffer, uint32_t bufsize)
116	{
117	    log_v("[%u], lba: %u, offset: %u, bufsize: %u", lun, lba, offset, bufsize);
118	    if(!msc_luns[lun].media_present){
119	        return 0;
120	    }
121	    if(msc_luns[lun].read){
122	        return msc_luns[lun].read(lba, offset, buffer, bufsize);
123	    }
124	    return 0;
125	}
126	
127	// Callback invoked when received WRITE10 command.
128	// Process data in buffer to disk's storage and return number of written bytes
129	int32_t tud_msc_write10_cb(uint8_t lun, uint32_t lba, uint32_t offset, uint8_t* buffer, uint32_t bufsize)
130	{
131	    log_v("[%u], lba: %u, offset: %u, bufsize: %u", lun, lba, offset, bufsize);
132	    if(!msc_luns[lun].media_present){
133	        return 0;
134	    }
135	    if(msc_luns[lun].write){
136	        return msc_luns[lun].write(lba, offset, buffer, bufsize);
137	    }
138	    return 0;
139	}
140	
141	// Callback invoked when received an SCSI command not in built-in list below
142	// - READ_CAPACITY10, READ_FORMAT_CAPACITY, INQUIRY, MODE_SENSE6, REQUEST_SENSE
143	// - READ10 and WRITE10 has their own callbacks
144	int32_t tud_msc_scsi_cb (uint8_t lun, uint8_t const scsi_cmd[16], void* buffer, uint16_t bufsize)
145	{
146	    // read10 & write10 has their own callback and MUST not be handled here
147	    log_v("[%u] cmd: %u, bufsize: %u", lun, scsi_cmd[0], bufsize);
148	
149	    void const* response = NULL;
150	    uint16_t resplen = 0;
151	
152	    // most scsi handled is input
153	    bool in_xfer = true;
154	    
155	    if(!msc_luns[lun].media_present){
156	        return -1;
157	    }
158	
159	    switch (scsi_cmd[0]) {
160	        case SCSI_CMD_PREVENT_ALLOW_MEDIUM_REMOVAL:
161	            // Host is about to read/write etc ... better not to disconnect disk
162	            resplen = 0;
163	            break;
164	
165	        default:
166	            // Set Sense = Invalid Command Operation
167	            tud_msc_set_sense(lun, SCSI_SENSE_ILLEGAL_REQUEST, 0x20, 0x00);
168	
169	            // negative means error -> tinyusb could stall and/or response with failed status
170	            resplen = -1;
171	            break;
172	    }
173	
174	    // return resplen must not larger than bufsize
175	    if (resplen > bufsize) resplen = bufsize;
176	
177	    if (response && (resplen > 0)) {
178	        if (in_xfer) {
179	            memcpy(buffer, response, resplen);
180	        } else {
181	            // SCSI output
182	        }
183	    }
184	
185	    return resplen;
186	}
