38	static int32_t usb_msc_read_cb(uint32_t lba, uint32_t offset, void* buffer, uint32_t bufsize) {
39	  // SDFS::readRAW reads exactly one 512-byte sector. The host can request
40	  // larger transfers, so loop until the buffer is full.
41	  const uint16_t sector_size = SD.sectorSize();
42	  if (sector_size == 0 || (bufsize % sector_size) != 0) {
43	    USB_LOG("read: bad geometry sector_size=%u bufsize=%u", sector_size, bufsize);
44	    return -1;
45	  }
46	  uint32_t sectors = bufsize / sector_size;
47	  uint8_t* dst = static_cast<uint8_t*>(buffer);
48	  for (uint32_t i = 0; i < sectors; ++i) {
49	    if (!SD.readRAW(dst + i * sector_size, lba + i)) {
50	      ++g_msc_read_fail_count;
51	      USB_LOG("read FAIL lba=%u (chunk %u/%u, offset=%u, bufsize=%u)",
52	              lba + i, i + 1, sectors, offset, bufsize);
53	      return -1;
54	    }
55	  }
56	  uint32_t n = ++g_msc_read_count;
57	  if (n <= 8 || (n % 512) == 0) {
58	    USB_LOG("read #%u lba=%u sectors=%u", n, lba, sectors);
59	  }
60	  return bufsize;
61	}
62	
63	static int32_t usb_msc_write_cb(uint32_t lba, uint32_t offset, uint8_t* buffer, uint32_t bufsize) {
64	  const uint16_t sector_size = SD.sectorSize();
65	  if (sector_size == 0 || (bufsize % sector_size) != 0) {
66	    USB_LOG("write: bad geometry sector_size=%u bufsize=%u", sector_size, bufsize);
67	    return -1;
68	  }
69	  uint32_t sectors = bufsize / sector_size;
70	  for (uint32_t i = 0; i < sectors; ++i) {
71	    if (!SD.writeRAW(buffer + i * sector_size, lba + i)) {
72	      ++g_msc_write_fail_count;
73	      USB_LOG("write FAIL lba=%u (chunk %u/%u, offset=%u, bufsize=%u)",
74	              lba + i, i + 1, sectors, offset, bufsize);
75	      return -1;
76	    }
77	  }
78	  uint32_t n = ++g_msc_write_count;
79	  if (n <= 8 || (n % 512) == 0) {
80	    USB_LOG("write #%u lba=%u sectors=%u", n, lba, sectors);
81	  }
82	  return bufsize;
83	}
