156	  if (current_time - _last_progress_update >= update_interval) {
157	    TransferState prev_state = _transfer_state;
158	    uint32_t prev_progress = _transfer_progress;
159	    updateUSBState();
160	    _last_progress_update = current_time;
161	    if (_transfer_state != prev_state || _transfer_progress != prev_progress) {
162	      force = true;
163	    }
164	  }
